preConditionHook:
// Off for holdBars bars starting with any bar that OPENED more than K x ATR
// away from the prior close (either direction). Bar-local, so it needs no
// session model: on intraday series a gap of that size essentially only
// occurs at a session open, on daily bars it is the overnight gap.
// holdBars = 1 blocks the gap bar's own signals (and flattens at the next
// open); raise it to cover a session's bars. The ATR includes the gap bar's
// own true range. Armed with a bool, not a sentinel; barsSinceGap counts
// every bar so the switch always expires.
//
// MultiWalk's WFSafe_AvgTrueRange is a ROLLING accumulator: seeded with a
// full N-term sum on the study's first calculated bar, thereafter
// S += TrueRange; S -= TrueRange[Length], re-seeding when the length changes.
// AtrProfitTarget is the reference and carries the measurement notes; the
// re-seed and the TWO-statement update are both load-bearing.
if (atrLength != (int)atrLookback) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLength = (int)atrLookback;
} else {
    const int out = (int)atrLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atr = atrSum / (int)atrLookback;
if (el_gt(std::fabs(open[0] - close[1]), gapAtrMultiple * atr)) {
    gapSeen = true;
    barsSinceGap = 0;
} else {
    barsSinceGap = barsSinceGap + 1;
}
